/// The curated verses the home card and the home-screen widget carry:
/// ninety short verses in a fixed rotation, and the verse of Salawat
/// on Fridays.
///
/// The list itself lives in `quran_verses.g.dart`, generated by
/// `tool/quran_verses.py` from the same QPC Uthmani text and the same
/// translations QuranTextService serves, cleaned the same way, so what
/// the card shows is letter for letter what the reel renders. The Android and iOS widgets carry their own copy of the
/// same list and the same arithmetic (see `VerseSchedule` on each
/// side), so they can turn the page without the app being opened; the
/// sync test keeps the three copies identical.
library;

import 'verse_translation.dart';

part 'quran_verses.g.dart';

/// A verse short enough to stand alone — a line or two of Uthmani
/// script, never a paragraph — with the exact text the reel will carry.
class QuranVerse {
  final int surah;
  final int startAyah;
  final int endAyah;

  /// The surah's English name as the surah index spells it, so the
  /// caption can be localized without a lookup.
  final String surahName;
  final String arabic;

  /// The translation in every edition the app offers, by its
  /// [VerseTranslation.code]. English is always present and is what
  /// everything falls back to.
  final Map<String, String> translations;

  /// What the card shows when the whole verse is more than a card
  /// should carry: its opening clause, up to the verse's own first
  /// pause mark. Null for the verses short enough to stand whole,
  /// which is most of them. The reel always carries the full verse.
  final String? excerpt;

  const QuranVerse({
    required this.surah,
    required this.startAyah,
    required this.endAyah,
    required this.surahName,
    required this.arabic,
    required this.translations,
    this.excerpt,
  });

  /// The line under the Arabic, in the edition Settings names.
  String translationIn(VerseTranslation t) =>
      translations[t.code] ?? translations['en']!;

  /// The English line. The two native home-screen widgets are not
  /// language-aware — neither is drawn by Flutter, and neither can
  /// read the app's settings — so their copy of the list carries this
  /// one, and the sync test compares against it.
  String get translation => translations['en']!;

  /// The Arabic the card and the widget set: the excerpt where there
  /// is one.
  String get shown => excerpt ?? arabic;

  /// '13:28' — the reference the card is captioned with.
  String get reference =>
      endAyah == startAyah ? '$surah:$startAyah' : '$surah:$startAyah–$endAyah';
}

/// Which verse the home card and the widget carry right now.
///
/// Two verses a day — one from midnight, another from noon — chosen by
/// counting half-days since a fixed epoch, so every phone shows the
/// same verse at the same hour and nobody sees one twice in forty-five
/// days. Friday is the Salawat verse all day and is left out of the
/// count, so no verse in the rotation is ever skipped over by it.
///
/// Pure arithmetic on the local calendar: nothing is stored, and the
/// native widgets do the same sums on their own copy of the list. Any
/// change here has to be made in `VerseSchedule.kt` and
/// `VerseSchedule.swift` too, or the widget and the card will disagree.
abstract final class QuranVerses {
  /// A Monday, long enough ago that no phone's clock is before it.
  static final DateTime epoch = DateTime.utc(2000, 1, 3);

  /// How many verses a day the rotation turns through.
  static const perDay = 2;

  /// Friday, by the phone's own calendar. Jumu'ah begins at Thursday's
  /// sunset by the Islamic day, but the card is read by people who
  /// think of it as Friday, and a card that turned over on Thursday
  /// evening would look like a bug to most of them.
  static bool isJumuah(DateTime d) => d.weekday == DateTime.friday;

  /// Calendar days since [epoch], by the local date. Done in UTC so a
  /// daylight-saving day of 23 or 25 hours still counts as one day.
  static int daysSinceEpoch(DateTime d) {
    final days = DateTime.utc(d.year, d.month, d.day).difference(epoch).inDays;
    return days < 0 ? 0 : days;
  }

  /// 0 before noon, 1 from noon.
  static int halfOf(DateTime d) => d.hour < 12 ? 0 : 1;

  /// The rotation slot: every half of every non-Friday day since the
  /// epoch, counted. The epoch is a Monday, so the Fridays before day
  /// `n` number `(n + 2) ~/ 7`.
  static int rotationSlot(DateTime d) {
    final days = daysSinceEpoch(d);
    final fridays = (days + 2) ~/ 7;
    return (days - fridays) * perDay + halfOf(d);
  }

  /// The slot the widget's background turns on: every half-day counted,
  /// Fridays included, so Friday and Saturday never share a picture.
  static int backgroundSlot(DateTime d) =>
      daysSinceEpoch(d) * perDay + halfOf(d);

  /// The verse for [date]: the Salawat verse on Friday, and otherwise
  /// the rotation's, by slot.
  static QuranVerse at(DateTime date) {
    if (isJumuah(date)) return jumuahVerse;
    return quranVerses[rotationSlot(date) % quranVerses.length];
  }

  /// When the verse after [date]'s takes over: noon, or midnight.
  static DateTime nextChange(DateTime date) => date.hour < 12
      ? DateTime(date.year, date.month, date.day, 12)
      : DateTime(date.year, date.month, date.day + 1);
}
